import { NextRequest, NextResponse } from 'next/server';

const BAZAARLINK_API_KEY = process.env.BAZAARLINK_API_KEY || '';
const BAZAARLINK_BASE_URL = 'https://bazaarlink.ai/api/v1';

export async function POST(request: NextRequest) {
  try {
    if (!BAZAARLINK_API_KEY) {
      return NextResponse.json(
        { error: 'API Key未配置' },
        { status: 500 }
      );
    }

    const body = await request.json();
    const { imageBase64 } = body;

    if (!imageBase64) {
      return NextResponse.json(
        { error: '请提供图片' },
        { status: 400 }
      );
    }

    const systemPrompt = `你是一名顶级专业图像分析师，拥有极致视觉敏锐度，精通美术影视摄影、设计美学、材质纹理、人文符号、构图光影等多领域专业知识库。

核心任务：对输入图像进行无遗漏、高精度全维度深度解构，严格遵循先宏观氛围、后微观细节的分析逻辑，全程使用专业术语，严禁主观臆断，严禁脑补画面不存在的内容。

强制规则：必须完整覆盖以下11个分析维度，缺一不可：基础属性、构图透视、光影布光、色彩色调、纹理材质、主体细节、场景空间、艺术风格、情绪氛围、符号内涵、画质质感。

交付规则：仅输出纯净标准JSON，不要输出任何其他内容，不要使用markdown代码块包裹。JSON格式如下：

{
  "基础属性": {
    "图像类型": "摄影/插画/3D渲染/油画/水彩/素描/动漫/其他",
    "画面方向": "横版/竖版/方形",
    "主体数量": "单人/双人/群体/无人物",
    "预估场景": "室内/室外/抽象/混合"
  },
  "构图透视": {
    "构图类型": "三分法/黄金分割/中心构图/对称构图/对角线/引导线/框架构图/其他",
    "视角": "平视/俯视/仰视/鸟瞰/虫眼",
    "景深": "浅景深/中景深/深景深",
    "空间层次": "前景描述/中景描述/背景描述"
  },
  "光影布光": {
    "光源类型": "自然光/人造光/混合光/环境光",
    "光线方向": "顺光/侧光/逆光/顶光/底光/侧逆光",
    "光线质感": "硬光/软光/漫射光",
    "光影效果": "明暗对比/光斑/阴影投射/体积光/伦勃朗光/其他",
    "色调温度": "暖调/冷调/中性"
  },
  "色彩色调": {
    "主色调": "主要颜色描述",
    "辅助色": "次要颜色描述",
    "色彩对比": "高对比/中对比/低对比",
    "色彩饱和度": "高饱和/中饱和/低饱和/去饱和",
    "配色风格": "互补色/类似色/单色/分裂互补"
  },
  "纹理材质": {
    "皮肤质感": "光滑/粗糙/细腻/其他",
    "服装材质": "丝绸/棉麻/皮革/纱质/金属/其他",
    "环境材质": "木质/石质/金属/玻璃/植物/布艺/其他",
    "特殊纹理": "如有特殊纹理请描述"
  },
  "主体细节": {
    "人物描述": "性别、年龄、发型、面部特征、表情、姿态",
    "服装描述": "款式、颜色、风格、细节装饰",
    "配饰道具": "饰品、手持物品、佩戴物等",
    "其他主体": "如有非人物主体请详细描述"
  },
  "场景空间": {
    "场景类型": "城市/自然/室内/幻想/抽象/历史/其他",
    "环境元素": "建筑、植物、天空、地面、水体等",
    "天气氛围": "晴天/阴天/雨天/雪天/雾气/其他",
    "时间感": "日出/白天/黄昏/夜晚"
  },
  "艺术风格": {
    "整体风格": "写实/印象派/赛博朋克/极简主义/复古/未来主义/其他",
    "参考流派": "可参考的艺术流派或摄影师风格",
    "处理手法": "HDR/胶片感/数字绘画/手绘/其他"
  },
  "情绪氛围": {
    "主情绪": "宁静/热烈/忧郁/神秘/欢快/紧张/浪漫/孤独/其他",
    "氛围关键词": ["关键词1", "关键词2", "关键词3"],
    "叙事感": "画面讲述的故事或暗示的情境"
  },
  "符号内涵": {
    "文化元素": "如有特定文化符号请描述",
    "象征意义": "画面中元素的隐喻或象征",
    "时代特征": "现代/古代/未来/跨时代"
  },
  "画质质感": {
    "清晰度": "高清晰/中等/柔和/朦胧",
    "颗粒感": "无颗粒/轻微颗粒/明显颗粒/胶片颗粒",
    "后期处理": "有无明显的后期调色/滤镜/特效",
    "整体品质": "专业级/商业级/业余/艺术创作"
  },
  "正向提示词": "基于以上分析，生成一段完整的英文AI绘图正向提示词，包含质量标签、风格、主体、细节、光影、构图等",
  "反向提示词": "生成对应的英文反向提示词"
}`;

    const response = await fetch(`${BAZAARLINK_BASE_URL}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${BAZAARLINK_API_KEY}`,
      },
      body: JSON.stringify({
        model: 'auto:free',
        messages: [
          {
            role: 'user',
            content: [
              {
                type: 'image_url',
                image_url: {
                  url: imageBase64.startsWith('data:')
                    ? imageBase64
                    : `data:image/jpeg;base64,${imageBase64}`,
                },
              },
              {
                type: 'text',
                text: '请对这张图片进行全维度深度解构分析，严格按照11个维度输出JSON。',
              },
            ],
          },
        ],
        max_tokens: 4000,
        temperature: 0.3,
      }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.error('BazaarLink API error:', errorText);
      return NextResponse.json(
        { error: 'AI服务调用失败' },
        { status: 500 }
      );
    }

    const data = await response.json();
    const content = data.choices[0]?.message?.content || '';

    // 解析JSON响应
    let jsonStr = content.trim();
    // 移除可能的 markdown 代码块包裹
    if (jsonStr.startsWith('```')) {
      jsonStr = jsonStr.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '');
    }

    const result = JSON.parse(jsonStr);
    return NextResponse.json(result);
  } catch (error) {
    console.error('Analyze image error:', error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : '未知错误' },
      { status: 500 }
    );
  }
}
